bindingset[s]
string getAnnotationText(string s) {
  // match `lgtm[...]` or `codeql[...]` anywhere in the comment
  result = s.regexpFind("(?i)\\b(lgtm|codeql)\\s*\\[[^\\]]*\\]", _, _).trim()
}

